A Go HTTP handler calls this for every request:

```go
func first(urls []string) string {
  ch := make(chan string)
  for _, u := range urls {
    go func(u string) {
      ch <- fetch(u)
    }(u)
  }
  return <-ch
}
```

Each call passes 4 URLs. Memory use rises steadily over days. Why?

What does this print?

```go
func gen(ns ...int) <-chan int {
  out := make(chan int)
  go func() {
    for _, n := range ns {
      out <- n
    }
    close(out)
  }()
  return out
}

func add1(in <-chan int) <-chan int {
  out := make(chan int)
  go func() {
    for n := range in {
      out <- n + 1
    }
    close(out)
  }()
  return out
}

func main() {
  s := 0
  c := add1(add1(gen(1, 2)))
  for v := range c {
    s += v
  }
  fmt.Println(s)
}
```

